KG42.register("rules-5d52664ceae9dfb39597a94c",{"id":"29-smart_home_trading::v141-c-R002","paper":"29-smart_home_trading","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"ECO-Trade aims to maximize the total benefits of all participating households, without differentiating households that generate surplus energy from those that do not. Scope: ECO-Trade objective across all participating households in the microgrid. Module 2 minimizes the total cost of all households as its sole objective and places the individual household cost objectives into inequality constraints. Scope: ECO-Trade Module 2 optimization for the participating microgrid households. Each participating household's total cost must be less than or equal to its cost when it does not participate. Scope: ECO-Trade Module 2, Constraint (24), restricting the total-cost optimization. Condition: When a household participates in microgrid trading.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.social_welfare"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"ECO-Trade Module 2 optimization for the participating microgrid households. | ECO-Trade Module 2, Constraint (24), restricting the total-cost optimization. | ECO-Trade objective across all participating households in the microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E06","v141-b-g01-E25","v141-b-g02-E20","v141-b-g02-E23"]},"x":[{"variable_id":"v141-c-R002-x-MP","symbol":"MP_h","meaning":"price of microgrid energy in Module 2","kind":"operational","domain":"\\mathbb{R}^+","unit":null,"indices":["h"],"evidence_ids":["v141-b-g01-E27","v141-b-g02-E16","v141-b-g01-E25"]},{"variable_id":"v141-c-R002-x-GE","symbol":"GE_{k,h}","meaning":"energy drawn from the grid by household k at timeslot h","kind":"operational","domain":"\\mathbb{R}^+","unit":"kWh","indices":["k","h"],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E12","v141-b-g01-E13"]},{"variable_id":"v141-c-R002-x-tau","symbol":"\\tau_{k,i}","meaning":"end time of appliance i operation for household k","kind":"operational","domain":"not explicitly specified in supplied source (end-time value)","unit":"timeslot","indices":["k","i"],"evidence_ids":["v141-b-g01-E12","v141-b-g01-E25","v141-b-g02-E11"]}],"theta":[{"parameter_id":"v141-c-R002-theta-GP","symbol":"GP_h","meaning":"grid energy price at timeslot h","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["h"],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E12","v141-b-g02-E18"]},{"parameter_id":"v141-c-R002-theta-ME","symbol":"ME_{k,h}","meaning":"energy traded in the microgrid; parameter in Module 2 and variable in Module 3","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["k","h"],"evidence_ids":["v141-b-g01-E27","v141-b-g01-E25","v141-b-g02-E16"]},{"parameter_id":"v141-c-R002-theta-CkNoTrade","symbol":"C_k^{NoTrade}","meaning":"total cost of the k-th household when it does not participate in microgrid energy trading; no-trade baseline from Module 1","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"cent","indices":["k"],"evidence_ids":["v141-b-g02-E23","v141-b-g01-E12"]},{"parameter_id":"v141-c-R002-theta-d","symbol":"d_{k,i}","meaning":"disutility factor of an appliance for household k and appliance i","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["k","i"],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E12"]},{"parameter_id":"v141-c-R002-theta-r","symbol":"r_{k,i,h}","meaning":"reservation-time boolean constant; r_{k,i,h}=1 means operation of the appliance is requested at timeslot h","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["k","i","h"],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E12"]},{"parameter_id":"v141-c-R002-theta-t","symbol":"t_{k,i}","meaning":"duration of the running time of appliance i for household k","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"timeslots","indices":["k","i"],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E12"]}],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"ECO-Trade aims to maximize the total benefits of all participating households, without differentiating households that generate surplus energy from those that do not. Scope: ECO-Trade objective across all participating households in the microgrid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E06"]},{"constraint_id":"v141-c-R002-C002","kind":"mathematical","role":"core","statement":"Module 2 minimizes the total cost of all households as its sole objective and places the individual household cost objectives into inequality constraints. Scope: ECO-Trade Module 2 optimization for the participating microgrid households.","expression":"\\min C_{total}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-GE","v141-c-R002-x-tau"],"parameter_refs":["v141-c-R002-theta-GP","v141-c-R002-theta-d","v141-c-R002-theta-r","v141-c-R002-theta-t"],"evidence_ids":["v141-b-g01-E25","v141-b-g02-E20"]},{"constraint_id":"v141-c-R002-C003","kind":"mathematical","role":"core","statement":"Each participating household's total cost must be less than or equal to its cost when it does not participate. Scope: ECO-Trade Module 2, Constraint (24), restricting the total-cost optimization. Condition: When a household participates in microgrid trading.","expression":"C_k \\le C_k^{NoTrade}, \\quad (k \\in K)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-MP","v141-c-R002-x-GE","v141-c-R002-x-tau"],"parameter_refs":["v141-c-R002-theta-GP","v141-c-R002-theta-ME","v141-c-R002-theta-CkNoTrade","v141-c-R002-theta-d","v141-c-R002-theta-r","v141-c-R002-theta-t"],"evidence_ids":["v141-b-g02-E23"]},{"constraint_id":"v141-c-R002-C004","kind":"mathematical","role":"supporting","statement":"Total cost of all households C_total is the sum over households and timeslots of grid energy cost plus the sum over households and appliances of disutility.","expression":"C_{total} = \\sum_{k \\in K} \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{k \\in K} \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-GE","v141-c-R002-x-tau"],"parameter_refs":["v141-c-R002-theta-GP","v141-c-R002-theta-d","v141-c-R002-theta-r","v141-c-R002-theta-t"],"evidence_ids":["v141-b-g02-E18","v141-b-g01-E25"]},{"constraint_id":"v141-c-R002-C005","kind":"mathematical","role":"supporting","statement":"Participating household cost C_k includes grid energy cost, microgrid energy payment at the microgrid price, and appliance disutility; this is the C_k bounded in the Pareto constraint (24).","expression":"C_k = \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{h \\in H} MP_h \\cdot ME_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R002-x-MP","v141-c-R002-x-GE","v141-c-R002-x-tau"],"parameter_refs":["v141-c-R002-theta-GP","v141-c-R002-theta-ME","v141-c-R002-theta-d","v141-c-R002-theta-r","v141-c-R002-theta-t"],"evidence_ids":["v141-b-g02-E19","v141-b-g01-E25"]}],"pi":[{"evidence_id":"v141-b-g01-E06","location":{"location_id":"src-7328a27ed1-p03-c1r1__v141-a-M01-validation","page":3,"printed_page":null,"section":"1. Introduction","anchor_text":"M.R. Alam et al. proposed algorithm aims at obtaining a socially optimal solution, i.e., m maximizin","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"example"},"source_text":"The proposed algorithm aims at obtaining a socially optimal solution, i.e., maximizing the total benefits of all participating households. Unlike other methods (e.g., [10]), it does not differentiate between the households who generate surplus energy and who do not."},{"evidence_id":"v141-b-g01-E25","location":{"location_id":"src-7328a27ed1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"microgrid energy MEk , h is a constant and microgrid energy price MPh is es a variable. 3.2.1. Objec","equation_id":"(17)-(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The proposed model in Module 2 is a multi-objective optimization problem which is expressed as (17). \\min (C_{total}, C_1, C_2, \\ldots, C_k) (17) Here, C_{total} is the total cost of all households and C_k is the total cost of the k-th household which are expressed in (18) and (19) respectively. C_{total} = \\sum_{k \\in K} \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{k \\in K} \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (18) C_k = \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{h \\in H} MP_h \\cdot ME_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (19)"},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-7328a27ed1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"me The total energy bought from the microgrid is the same as the total energy sold to the microgrid.","equation_id":"Eq. (20)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The total energy bought from the microgrid is the same as the total energy sold to the microgrid. Therefore, microgrid energy price does not have an impact on the total cost. Hence, Eq. (18) does not require the microgrid energy cost. This multi-objective optimization problem is solved by using C_{total} as the sole objective function and the remaining objective functions, C_{k}, are added as inequality constraints (Constraint (24) discussed later). Therefore, the objective function of Module 2 is defined as (20). \\min C_{total} \\quad (20)"},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-7328a27ed1-p06-c1r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"3.3 Module 3: Energy computation module","anchor_text":"fehousehold cost when it participates in microgrid trading must be less ththan or equal to the cost ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Constraint (24) implements Pareto optimality. It ensues that a household cost when it participates in microgrid trading must be less than or equal to the cost when it does not participate. C_{k} \\le C_{k}^{NoTrade}, \\quad (k \\in K) \\quad (24)"},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-7328a27ed1-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1.1 Objective function","anchor_text":"Applied Energy 238 (2019) 1434–1443 y, 3.1. Module 1: Initial demand and supply module al al- Module","equation_id":"(1)-(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"If a household does not participate in microgrid energy trading, its energy cost is expressed as (1). C_k^{NoTrade} = \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (1) The objective function is defined as (2), \\min C_k^{NoTrade} (2) where C_k^{NoTrade} is the total cost of the k-th household when it does not participate in microgrid energy trading, GP_h is the grid energy price, GE_{k,h} is the amount of energy drawn from the grid, d_{k,i} is the disutility factor of an appliance, and r_{k,i,h} is the reservation time of an appliance which represents the time when the scheduler gets a request to start a specific appliance."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-7328a27ed1-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1.2 Energy balance constraints","anchor_text":"ed sumed by the loads should be the same as the total energy generated by of the energy sources. In ","equation_id":"(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Constraint (3) ensures the balance of energy consumption and generation in each timeslot for all households. The total energy consumed by the loads should be the same as the total energy generated by the energy sources. In this constraint, the grid and renewables are energy sources and the home appliances are loads. The storage and the microgrid can be energy sources or loads based on their functionalities in each timeslot. \\sum_{i \\in I} S_{k,i,h} \\cdot p_{k,i} + IC_{k,h} \\cdot SP_k = GE_{k,h} + BE_{k,h} + RE_{k,h}, \\quad (k \\in K, h \\in H) (3) where S_{k,i,h} represents the appliance operation time, p_{k,i} is the power consumption of an appliance, IC_{k,h} represents the storage charging state, SP_k is the required power to charge the storage, BE_{k,h} is the amount of energy used from the storage, and RE_{k,h} is the amount of energy used from the renewable source."},{"evidence_id":"v141-b-g01-E27","location":{"location_id":"src-7328a27ed1-p02-c2r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"MQk , h demand or supply of microgrid energy (MQk , h , a po- sitive value represents the minimum en","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"DS_{k,h} energy demand or supply of a household (DS_{k,h} \\in \\mathbb{R}, a positive value represents energy demand and a negative value represents energy surplus). DS_{k,h} is a variable in Module 1 and a parameter in Module 2 ME_{k,h} energy traded in microgrid (ME_{k,h} \\in \\mathbb{R}, a positive value represents a buyer and a negative value represents a seller). ME_{k,h} is a parameter in Module 2 and a variable in Module 3 MP_h price of microgrid energy (MP_h \\in \\mathbb{R}^+). MP_h is a variable in Module 2 and a parameter in Module 3"},{"evidence_id":"v141-b-g02-E11","location":{"location_id":"src-7328a27ed1-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.9 Maximum allowable delay constraints","anchor_text":"3.1.8. Relationship between the Scheduling Vector and the End Time Constraints en Constraint (11) bi","equation_id":"Eqs. (11)-(14)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"\\tau_{k,i} \\le \\beta_{k,i}, \\quad (k \\in K, i \\in I) \\quad (12)"},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-7328a27ed1-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.12 Demand and supply constraints","anchor_text":"y g p Constraint (15) limits the power that can be drawn from the grid. 6) GEk , h Lkmax , ( k K , h","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Module 2 computes the microgrid energy price. In this module, microgrid energy ME_{k,h} is a constant and microgrid energy price MP_{h} is a variable."},{"evidence_id":"v141-b-g02-E18","location":{"location_id":"src-7328a27ed1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"microgrid energy MEk , h is a constant and microgrid energy price MPh is es a variable. 3.2.1. Objec","equation_id":"Eqs. (17)-(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"C_{total} = \\sum_{k \\in K} \\sum_{h \\in H} GP_{h} \\cdot GE_{k,h} + \\sum_{k \\in K} \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) \\quad (18)"},{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-7328a27ed1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"microgrid energy MEk , h is a constant and microgrid energy price MPh is es a variable. 3.2.1. Objec","equation_id":"Eqs. (17)-(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"C_{k} = \\sum_{h \\in H} GP_{h} \\cdot GE_{k,h} + \\sum_{h \\in H} MP_{h} \\cdot ME_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) \\quad (19)"}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E06","quote":"The proposed algorithm aims at obtaining a socially optimal solution, i.e., maximizing the total benefits of all participating households. Unlike other methods (e.g., [10]), it does not differentiate between the households who generate surplus energy and who do not."}],[{"evidence_id":"v141-b-g01-E25","quote":"Here, C_{total} is the total cost of all households and C_k is the total cost of the k-th household which are expressed in (18) and (19) respectively."},{"evidence_id":"v141-b-g02-E20","quote":"This multi-objective optimization problem is solved by using C_{total} as the sole objective function and the remaining objective functions, C_{k}, are added as inequality constraints (Constraint (24) discussed later). Therefore, the objective function of Module 2 is defined as (20). \\min C_{total} \\quad (20)"}],[{"evidence_id":"v141-b-g02-E23","quote":"Constraint (24) implements Pareto optimality. It ensues that a household cost when it participates in microgrid trading must be less than or equal to the cost when it does not participate."}]],"C2_formalization":{"graph_sha256":"39ba28008437b5ca48493d04c21b43a53cdc32660b7e6f4a17dcc087b39337bc","applicability":"formalized","reason":"The supplied source supports formalizing the Module 2 sole objective (20), the household cost definition (19), the total-cost definition (18), and the Pareto no-worse-off inequality (24). The qualitative C001 statement remains not_formalized because the supplied evidence only says 'maximizing total benefits' without an exact expression. B evidence is unreviewed; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R002-C001","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Qualitative social-welfare statement attached to the clearing.social_welfare function node. The frozen graph has no E edges; no relation is inferred beyond membership."},{"object_id":"v141-c-R002-C002","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Module 2 sole objective min C_total is an internal objective of clearing.social_welfare. C_total is defined in C004. The frozen graph has no E edges."},{"object_id":"v141-c-R002-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Pareto no-worse-off inequality restricts household cost C_k, defined in C005, relative to C_k^NoTrade. This is an internal condition of clearing.social_welfare; no E edge exists in the frozen graph."},{"object_id":"v141-c-R002-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Definition of total cost used by C002, internal to the social-welfare clearing function. No edge is added because E is empty."},{"object_id":"v141-c-R002-C005","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Definition of participating household cost used by C003, internal to the social-welfare clearing function. No edge is added because E is empty."},{"object_id":"v141-c-R002-x-MP","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"MP_h is the explicitly identified Module 2 decision variable; it enters C_k in C005 and is bounded through the social-welfare Pareto constraint C003. No graph edge is available."},{"object_id":"v141-c-R002-x-GE","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"GE_{k,h} is a grid-energy decision variable entering the total-cost and household-cost expressions C004 and C005. It is bound to the social-welfare clearing objective; no edge exists."},{"object_id":"v141-c-R002-x-tau","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"tau_{k,i} is the appliance end-time variable entering the disutility term of C004 and C005. It is bound to the social-welfare clearing objective; no edge exists."},{"object_id":"v141-c-R002-theta-GP","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"GP_h is a fixed grid-price parameter in the total-cost and household-cost formulas. It is bound to clearing.social_welfare; no edge exists."},{"object_id":"v141-c-R002-theta-ME","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"ME_{k,h} is a parameter in Module 2 and enters the household-cost definition C005. It is bound to clearing.social_welfare; no edge exists."},{"object_id":"v141-c-R002-theta-CkNoTrade","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C_k^NoTrade is the no-trade baseline on the right-hand side of the Pareto inequality C003. It is bound to clearing.social_welfare; no edge exists."},{"object_id":"v141-c-R002-theta-d","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"d_{k,i} is a fixed disutility coefficient in the cost formulas C004 and C005. It is bound to clearing.social_welfare; no edge exists."},{"object_id":"v141-c-R002-theta-r","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"r_{k,i,h} is a reservation-time boolean constant in the disutility term of C004 and C005. It is bound to clearing.social_welfare; no edge exists."},{"object_id":"v141-c-R002-theta-t","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"t_{k,i} is a fixed appliance-duration parameter in the disutility term of C004 and C005. It is bound to clearing.social_welfare; no edge exists."}],"revision_requests":[]}},"quarantined_references":[]}});
